package com.kzplayer.app;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.*;

/** Real production binary-cache code, ordinary JVM files; no SQLite/Robolectric substitute. */
public class SearchCatalogStoreTest {
    private File directory()throws IOException{return Files.createTempDirectory("kz-search-test-").toFile();}
    private SearchCatalogStore.Row row(String id,String title){return new SearchCatalogStore.Row(id,title,"payload:"+id);}
    @Test public void searchesEveryOneOfEightSources()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){for(int i=0;i<8;i++){String key="source"+i;s.put(key,"a",Arrays.asList(row("1","Le Grinch")));s.complete(key,"a");assertEquals("payload:1",s.find(key,"grinch").get(0));}}}
    @Test public void supportsAccentsLigaturesSubstringsAndAllWords()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("p","a",Arrays.asList(row("1","L'Île aux Bœufs"),row("2","Harry Potter et le Prince")));s.complete("p","a");assertEquals(1,s.find("p","ile boeuf").size());assertEquals(1,s.find("p","arry prince").size());assertTrue(s.find("p","arry grinch").isEmpty());}}
    @Test public void identitiesStayIsolatedByPlaylist()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("a","1",Arrays.asList(row("same","Film rouge")));s.put("b","1",Arrays.asList(row("same","Film bleu")));assertTrue(s.find("a","bleu").isEmpty());assertEquals(1,s.find("b","bleu").size());}}
    @Test public void partialBatchesAreSearchableBeforeCompletion()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("p","a",Arrays.asList(row("1","Le Grinch")));assertEquals(1,s.find("p","grinch").size());assertEquals(0L,s.updated("p"));}}
    @Test public void refreshRetainsLastKnownUntilNewCatalogCommits()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("p","old",Arrays.asList(row("1","Film ancien")));s.complete("p","old");s.put("p","new",Arrays.asList(row("2","Le Grinch")));assertEquals(1,s.find("p","ancien").size());assertEquals(1,s.find("p","grinch").size());s.complete("p","new");assertTrue(s.find("p","ancien").isEmpty());}}
    @Test public void updatesDoNotDuplicateAnIdentity()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("p","a",Arrays.asList(row("1","Le Grinch")));s.put("p","a",Arrays.asList(row("1","Le Grinch nouvelle edition")));assertEquals(1,s.find("p","grinch").size());s.complete("p","a");assertEquals(1,s.find("p","edition").size());}}
    @Test public void completedCatalogSurvivesCloseAndReopen()throws Exception{File dir=directory();try(SearchCatalogStore s=new SearchCatalogStore(dir)){s.put("p","a",Arrays.asList(row("1","Le Grinch")));s.complete("p","a");}try(SearchCatalogStore s=new SearchCatalogStore(dir)){assertTrue(s.updated("p")>0);assertEquals(1,s.find("p","grinch").size());}}
    @Test public void unfinishedRefreshDoesNotDestroySavedCatalog()throws Exception{File dir=directory();try(SearchCatalogStore s=new SearchCatalogStore(dir)){s.put("p","old",Arrays.asList(row("1","Film conserve")));s.complete("p","old");s.put("p","new",Arrays.asList(row("2","Film incomplet")));}try(SearchCatalogStore s=new SearchCatalogStore(dir)){assertEquals(1,s.find("p","conserve").size());assertTrue(s.find("p","incomplet").isEmpty());}}
    @Test public void nativeQueriesAccumulateAndPersistTheirCompletion()throws Exception{File dir=directory();try(SearchCatalogStore s=new SearchCatalogStore(dir)){s.put("p","native",Arrays.asList(row("1","Le Grinch")));s.completeQuery("p","grinch",false);s.put("p","native",Arrays.asList(row("2","Harry Potter")));s.completeQuery("p","harry",true);assertEquals(1,s.find("p","grinch").size());assertEquals(1,s.find("p","harry").size());}try(SearchCatalogStore s=new SearchCatalogStore(dir)){assertEquals(0,s.queryState("p","grinch",0));assertEquals(1,s.queryState("p","harry",0));assertEquals(-1,s.queryState("p","absent",0));}}
    @Test public void validEmptyNativeQueryDoesNotEraseOtherResults()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.put("p","native",Arrays.asList(row("1","Le Grinch")));s.completeQuery("p","grinch",false);s.completeQuery("p","absent",false);assertEquals(0,s.queryState("p","absent",0));assertEquals(1,s.find("p","grinch").size());}}
    @Test public void invalidationForcesRefreshWithoutDeletingResults()throws Exception{File dir=directory();try(SearchCatalogStore s=new SearchCatalogStore(dir)){s.put("p","native",Arrays.asList(row("1","Le Grinch")));s.completeQuery("p","grinch",false);s.invalidate();assertEquals(0L,s.updated("p"));assertEquals(-1,s.queryState("p","grinch",0));assertEquals(1,s.find("p","grinch").size());}try(SearchCatalogStore s=new SearchCatalogStore(dir)){assertEquals(0L,s.updated("p"));assertEquals(1,s.find("p","grinch").size());}}
    @Test public void corruptManifestRebuildsInsteadOfPoisoningEverySource()throws Exception{File dir=directory();try(SearchCatalogStore s=new SearchCatalogStore(dir)){s.put("p","a",Arrays.asList(row("1","Grinch")));s.complete("p","a");}try(FileOutputStream out=new FileOutputStream(new File(dir,"p.idx"))){out.write(1);}try(SearchCatalogStore s=new SearchCatalogStore(dir)){assertEquals(0L,s.updated("p"));s.put("p","new",Arrays.asList(row("2","Grinch")));s.complete("p","new");assertEquals("payload:2",s.find("p","grinch").get(0));}}
    @Test public void exactTitleIsKeptEvenAfterManyFragmentMatches()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){List<SearchCatalogStore.Row> rows=new ArrayList<>();for(int n=0;n<500;n++)rows.add(row("x"+n,"Le Grinch collection "+n));rows.add(row("exact","Le Grinch"));s.put("p","a",rows);s.complete("p","a");List<String> found=s.find("p","le grinch");assertEquals("payload:exact",found.get(0));assertEquals(SearchCatalogStore.PER_LIST_LIMIT+1,found.size());}}
    @Test public void concurrentSourceWritesAndQueriesDoNotMixAccounts()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){ExecutorService pool=Executors.newFixedThreadPool(4);try{List<Future<?>> jobs=new ArrayList<>();for(int n=0;n<4;n++){final int k=n;jobs.add(pool.submit(()->{for(int i=0;i<100;i++)s.put("p"+k,"a",Arrays.asList(row("id"+i,"Film source"+k+" numero "+i)));s.complete("p"+k,"a");assertEquals(1,s.find("p"+k,"numero 99").size());assertTrue(s.find("p"+k,"source"+((k+1)%4)).isEmpty());}));}for(Future<?> job:jobs)job.get();}finally{pool.shutdownNow();}}}
    @Test(expected=IllegalArgumentException.class) public void rejectsPathsAsCatalogKeys()throws Exception{try(SearchCatalogStore s=new SearchCatalogStore(directory())){s.find("../outside","grinch");}}
}
